 "content": "def transform(grid):
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda c: sum(x == c for row in grid for x in row))
    # For each line, fill the background cell between equal non-background markers.
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(1, w - 1):
            if grid[r][c] == bg and grid[r][c-1] == grid[r][c+1] != bg:
                out[r][c] = 2
    for r in range(1, h - 1):
        for c in range(w):
            if grid[r][c] == bg and grid[r-1][c] == grid[r+1][c] != bg:
                out[r][c] = 2
